package com.gamehub.admin;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.gamehub.admin.entity.AdminUser;import com.gamehub.admin.repository.AdminUserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import java.time.LocalDateTime;
@Component public class AdminBootstrap implements CommandLineRunner {private final AdminUserRepository repo;private final PasswordEncoder encoder;private final String username;private final String password;public AdminBootstrap(AdminUserRepository repo,PasswordEncoder encoder,@Value("${gamehub.admin.username}")String username,@Value("${gamehub.admin.password}")String password){this.repo=repo;this.encoder=encoder;this.username=username;this.password=password;}public void run(String...args){if(repo.selectCount(new LambdaQueryWrapper<AdminUser>().eq(AdminUser::getUsername,username))==0){AdminUser u=new AdminUser();u.setUsername(username);u.setPasswordHash(encoder.encode(password));u.setEnabled(true);u.setCreatedAt(LocalDateTime.now());u.setUpdatedAt(LocalDateTime.now());repo.insert(u);}}}
